    functionParameter: {
      x: { name: "x", detail: "\u041E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0439. \u0417\u043D\u0430\u0447\u0435\u043D\u0438\u0435, \u0434\u043B\u044F \u043A\u043E\u0442\u043E\u0440\u043E\u0433\u043E \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u0432\u044B\u0447\u0438\u0441\u043B\u0438\u0442\u044C \u0440\u0430\u0441\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0438\u0435." },
      degFreedom: { name: "\u0441\u0442\u0435\u043F\u0435\u043D\u0438 \u0441\u0432\u043E\u0431\u043E\u0434\u044B", detail: "\u041E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E. \u0427\u0438\u0441\u043B\u043E \u0441\u0442\u0435\u043F\u0435\u043D\u0435\u0439 \u0441\u0432\u043E\u0431\u043E\u0434\u044B." }
    }
