    functionParameter: {
      trials: { name: "\u0447\u0438\u0441\u043B\u043E \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u0439", detail: "\u041E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E. \u0427\u0438\u0441\u043B\u043E \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u0439 \u0411\u0435\u0440\u043D\u0443\u043B\u043B\u0438." },
      probabilityS: { name: "\u0432\u0435\u0440\u043E\u044F\u0442\u043D\u043E\u0441\u0442\u044C \u0443\u0441\u043F\u0435\u0445\u0430 ", detail: "\u041E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E. \u0412\u0435\u0440\u043E\u044F\u0442\u043D\u043E\u0441\u0442\u044C \u0443\u0441\u043F\u0435\u0445\u0430 \u0432 \u043A\u0430\u0436\u0434\u043E\u043C \u0438\u0441\u043F\u044B\u0442\u0430\u043D\u0438\u0438." },
      alpha: { name: "\u0430\u043B\u044C\u0444\u0430", detail: "\u041E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E. \u0417\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u043A\u0440\u0438\u0442\u0435\u0440\u0438\u044F." }
    }
