      array1: { name: "\u043C\u0430\u0441\u0441\u0438\u04321", detail: "\u041E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E. \u041F\u0435\u0440\u0432\u044B\u0439 \u043D\u0430\u0431\u043E\u0440 \u0434\u0430\u043D\u043D\u044B\u0445." },
