      pivotTable: { name: "\u0421\u0432\u043E\u0434\u043D\u0430\u044F \u0442\u0430\u0431\u043B\u0438\u0446\u0430", detail: "\u0421\u0441\u044B\u043B\u043A\u0430 \u043D\u0430 \u044F\u0447\u0435\u0439\u043A\u0443, \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D \u0438\u043B\u0438 \u0438\u043C\u0435\u043D\u043E\u0432\u0430\u043D\u043D\u044B\u0439 \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D \u0441\u0432\u043E\u0434\u043D\u043E\u0439 \u0442\u0430\u0431\u043B\u0438\u0446\u044B." },
