      criteria: { name: "\u0443\u0441\u043B\u043E\u0432\u0438\u0435", detail: '\u0427\u0438\u0441\u043B\u043E, \u0432\u044B\u0440\u0430\u0436\u0435\u043D\u0438\u0435, \u0441\u0441\u044B\u043B\u043A\u0430 \u043D\u0430 \u044F\u0447\u0435\u0439\u043A\u0443 \u0438\u043B\u0438 \u0442\u0435\u043A\u0441\u0442\u043E\u0432\u0430\u044F \u0441\u0442\u0440\u043E\u043A\u0430, \u043A\u043E\u0442\u043E\u0440\u0430\u044F \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442, \u043A\u0430\u043A\u0438\u0435 \u044F\u0447\u0435\u0439\u043A\u0438 \u043D\u0443\u0436\u043D\u043E \u043F\u043E\u0434\u0441\u0447\u0438\u0442\u0430\u0442\u044C. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043A\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u0432\u044B\u0440\u0430\u0436\u0435\u043D \u043A\u0430\u043A 32, ">32", \u04124, "\u044F\u0431\u043B\u043E\u043A\u0438" \u0438\u043B\u0438 "32".' }
