      criteriaRange2: { name: "\u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D \u0443\u0441\u043B\u043E\u0432\u0438\u04392", detail: "\u0414\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D\u044B. \u0412\u044B \u043C\u043E\u0436\u0435\u0442\u0435 \u0432\u0432\u0435\u0441\u0442\u0438 \u0434\u043E 127 \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D\u043E\u0432." },
