      constb: { name: "\u043A\u043E\u043D\u0441\u0442", detail: "\u041B\u043E\u0433\u0438\u0447\u0435\u0441\u043A\u043E\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435, \u043A\u043E\u0442\u043E\u0440\u043E\u0435 \u0443\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442, \u0434\u043E\u043B\u0436\u043D\u0430 \u043B\u0438 \u043A\u043E\u043D\u0441\u0442\u0430\u043D\u0442\u0430 b \u0440\u0430\u0432\u043D\u044F\u0442\u044C\u0441\u044F 1." }
