    "\u{1F9D7}\u{1F3FE}": "\u0447\u0435\u043B\u043E\u0432\u0435\u043A \u0432\u0437\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044F \u043F\u043E \u0441\u043A\u0430\u043B\u0435: \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F9D7}\u{1F3FF}": "\u0447\u0435\u043B\u043E\u0432\u0435\u043A \u0432\u0437\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044F \u043F\u043E \u0441\u043A\u0430\u043B\u0435: \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
