    "\u26F9\u{1F3FB}\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u0441 \u043C\u044F\u0447\u043E\u043C: \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u26F9\u{1F3FC}\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u0441 \u043C\u044F\u0447\u043E\u043C: \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u26F9\u{1F3FD}\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u0441 \u043C\u044F\u0447\u043E\u043C: \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u26F9\u{1F3FE}\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u0441 \u043C\u044F\u0447\u043E\u043C: \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u26F9\u{1F3FF}\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u0441 \u043C\u044F\u0447\u043E\u043C: \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F3CB}\uFE0F": "\u0442\u044F\u0436\u0435\u043B\u043E\u0430\u0442\u043B\u0435\u0442",
    "\u{1F3CB}\u{1F3FB}": "\u0442\u044F\u0436\u0435\u043B\u043E\u0430\u0442\u043B\u0435\u0442: \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F3CB}\u{1F3FC}": "\u0442\u044F\u0436\u0435\u043B\u043E\u0430\u0442\u043B\u0435\u0442: \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F3CB}\u{1F3FD}": "\u0442\u044F\u0436\u0435\u043B\u043E\u0430\u0442\u043B\u0435\u0442: \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F3CB}\u{1F3FE}": "\u0442\u044F\u0436\u0435\u043B\u043E\u0430\u0442\u043B\u0435\u0442: \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F3CB}\u{1F3FF}": "\u0442\u044F\u0436\u0435\u043B\u043E\u0430\u0442\u043B\u0435\u0442: \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F3CB}\uFE0F\u200D\u2642\uFE0F": "\u043C\u0443\u0436\u0447\u0438\u043D\u0430 \u0441\u043E \u0448\u0442\u0430\u043D\u0433\u043E\u0439",
    "\u{1F3CB}\u{1F3FB}\u200D\u2642\uFE0F": "\u043C\u0443\u0436\u0447\u0438\u043D\u0430 \u0441\u043E \u0448\u0442\u0430\u043D\u0433\u043E\u0439: \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F3CB}\u{1F3FC}\u200D\u2642\uFE0F": "\u043C\u0443\u0436\u0447\u0438\u043D\u0430 \u0441\u043E \u0448\u0442\u0430\u043D\u0433\u043E\u0439: \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F3CB}\u{1F3FD}\u200D\u2642\uFE0F": "\u043C\u0443\u0436\u0447\u0438\u043D\u0430 \u0441\u043E \u0448\u0442\u0430\u043D\u0433\u043E\u0439: \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F3CB}\u{1F3FE}\u200D\u2642\uFE0F": "\u043C\u0443\u0436\u0447\u0438\u043D\u0430 \u0441\u043E \u0448\u0442\u0430\u043D\u0433\u043E\u0439: \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F3CB}\u{1F3FF}\u200D\u2642\uFE0F": "\u043C\u0443\u0436\u0447\u0438\u043D\u0430 \u0441\u043E \u0448\u0442\u0430\u043D\u0433\u043E\u0439: \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F3CB}\uFE0F\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u0441\u043E \u0448\u0442\u0430\u043D\u0433\u043E\u0439",
    "\u{1F3CB}\u{1F3FB}\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u0441\u043E \u0448\u0442\u0430\u043D\u0433\u043E\u0439: \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
