    "\u{1F3CB}\u{1F3FD}\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u0441\u043E \u0448\u0442\u0430\u043D\u0433\u043E\u0439: \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F3CB}\u{1F3FE}\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u0441\u043E \u0448\u0442\u0430\u043D\u0433\u043E\u0439: \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F3CB}\u{1F3FF}\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u0441\u043E \u0448\u0442\u0430\u043D\u0433\u043E\u0439: \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B4}": "\u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0438\u0441\u0442",
    "\u{1F6B4}\u{1F3FB}": "\u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0438\u0441\u0442: \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B4}\u{1F3FC}": "\u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0438\u0441\u0442: \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B4}\u{1F3FD}": "\u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0438\u0441\u0442: \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B4}\u{1F3FE}": "\u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0438\u0441\u0442: \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B4}\u{1F3FF}": "\u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0438\u0441\u0442: \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B4}\u200D\u2642\uFE0F": "\u043C\u0443\u0436\u0447\u0438\u043D\u0430 \u043D\u0430 \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435",
    "\u{1F6B4}\u{1F3FB}\u200D\u2642\uFE0F": "\u043C\u0443\u0436\u0447\u0438\u043D\u0430 \u043D\u0430 \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435: \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B4}\u{1F3FC}\u200D\u2642\uFE0F": "\u043C\u0443\u0436\u0447\u0438\u043D\u0430 \u043D\u0430 \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435: \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B4}\u{1F3FD}\u200D\u2642\uFE0F": "\u043C\u0443\u0436\u0447\u0438\u043D\u0430 \u043D\u0430 \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435: \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B4}\u{1F3FE}\u200D\u2642\uFE0F": "\u043C\u0443\u0436\u0447\u0438\u043D\u0430 \u043D\u0430 \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435: \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B4}\u{1F3FF}\u200D\u2642\uFE0F": "\u043C\u0443\u0436\u0447\u0438\u043D\u0430 \u043D\u0430 \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435: \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B4}\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u043D\u0430 \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435",
    "\u{1F6B4}\u{1F3FB}\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u043D\u0430 \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435: \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B4}\u{1F3FC}\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u043D\u0430 \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435: \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B4}\u{1F3FD}\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u043D\u0430 \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435: \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B4}\u{1F3FE}\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u043D\u0430 \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435: \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B4}\u{1F3FF}\u200D\u2640\uFE0F": "\u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u043D\u0430 \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435: \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B5}": "\u0447\u0435\u043B\u043E\u0432\u0435\u043A \u043D\u0430 \u0433\u043E\u0440\u043D\u043E\u043C \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435",
    "\u{1F6B5}\u{1F3FB}": "\u0447\u0435\u043B\u043E\u0432\u0435\u043A \u043D\u0430 \u0433\u043E\u0440\u043D\u043E\u043C \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435: \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B5}\u{1F3FC}": "\u0447\u0435\u043B\u043E\u0432\u0435\u043A \u043D\u0430 \u0433\u043E\u0440\u043D\u043E\u043C \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435: \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F6B5}\u{1F3FD}": "\u0447\u0435\u043B\u043E\u0432\u0435\u043A \u043D\u0430 \u0433\u043E\u0440\u043D\u043E\u043C \u0432\u0435\u043B\u043E\u0441\u0438\u043F\u0435\u0434\u0435: \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
