    "\u{1F469}\u{1F3FD}\u200D\u{1F91D}\u200D\u{1F468}\u{1F3FF}": "\u043C\u0443\u0436\u0447\u0438\u043D\u0430 \u0438 \u0436\u0435\u043D\u0449\u0438\u043D\u0430: \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F469}\u{1F3FE}\u200D\u{1F91D}\u200D\u{1F468}\u{1F3FB}": "\u043C\u0443\u0436\u0447\u0438\u043D\u0430 \u0438 \u0436\u0435\u043D\u0449\u0438\u043D\u0430: \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
