    "\u{1F468}\u{1F3FD}\u200D\u{1F91D}\u200D\u{1F468}\u{1F3FF}": "\u0434\u0432\u043E\u0435 \u043C\u0443\u0436\u0447\u0438\u043D: \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F468}\u{1F3FE}\u200D\u{1F91D}\u200D\u{1F468}\u{1F3FB}": "\u0434\u0432\u043E\u0435 \u043C\u0443\u0436\u0447\u0438\u043D: \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F468}\u{1F3FE}\u200D\u{1F91D}\u200D\u{1F468}\u{1F3FC}": "\u0434\u0432\u043E\u0435 \u043C\u0443\u0436\u0447\u0438\u043D: \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F468}\u{1F3FE}\u200D\u{1F91D}\u200D\u{1F468}\u{1F3FD}": "\u0434\u0432\u043E\u0435 \u043C\u0443\u0436\u0447\u0438\u043D: \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F46C}\u{1F3FE}": "\u0434\u0432\u043E\u0435 \u043C\u0443\u0436\u0447\u0438\u043D: \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F468}\u{1F3FE}\u200D\u{1F91D}\u200D\u{1F468}\u{1F3FF}": "\u0434\u0432\u043E\u0435 \u043C\u0443\u0436\u0447\u0438\u043D: \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F468}\u{1F3FF}\u200D\u{1F91D}\u200D\u{1F468}\u{1F3FB}": "\u0434\u0432\u043E\u0435 \u043C\u0443\u0436\u0447\u0438\u043D: \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F468}\u{1F3FF}\u200D\u{1F91D}\u200D\u{1F468}\u{1F3FC}": "\u0434\u0432\u043E\u0435 \u043C\u0443\u0436\u0447\u0438\u043D: \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F468}\u{1F3FF}\u200D\u{1F91D}\u200D\u{1F468}\u{1F3FD}": "\u0434\u0432\u043E\u0435 \u043C\u0443\u0436\u0447\u0438\u043D: \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F468}\u{1F3FF}\u200D\u{1F91D}\u200D\u{1F468}\u{1F3FE}": "\u0434\u0432\u043E\u0435 \u043C\u0443\u0436\u0447\u0438\u043D: \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F46C}\u{1F3FF}": "\u0434\u0432\u043E\u0435 \u043C\u0443\u0436\u0447\u0438\u043D: \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F48F}": "\u043F\u043E\u0446\u0435\u043B\u0443\u0439",
    "\u{1F48F}\u{1F3FB}": "\u043F\u043E\u0446\u0435\u043B\u0443\u0439: \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F48F}\u{1F3FC}": "\u043F\u043E\u0446\u0435\u043B\u0443\u0439: \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F48F}\u{1F3FD}": "\u043F\u043E\u0446\u0435\u043B\u0443\u0439: \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F48F}\u{1F3FE}": "\u043F\u043E\u0446\u0435\u043B\u0443\u0439: \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F48F}\u{1F3FF}": "\u043F\u043E\u0446\u0435\u043B\u0443\u0439: \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F9D1}\u{1F3FB}\u200D\u2764\uFE0F\u200D\u{1F48B}\u200D\u{1F9D1}\u{1F3FC}": "\u043F\u043E\u0446\u0435\u043B\u0443\u0439: \u0432\u0437\u0440\u043E\u0441\u043B\u044B\u0439 \u0432\u0437\u0440\u043E\u0441\u043B\u044B\u0439 \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F9D1}\u{1F3FB}\u200D\u2764\uFE0F\u200D\u{1F48B}\u200D\u{1F9D1}\u{1F3FD}": "\u043F\u043E\u0446\u0435\u043B\u0443\u0439: \u0432\u0437\u0440\u043E\u0441\u043B\u044B\u0439 \u0432\u0437\u0440\u043E\u0441\u043B\u044B\u0439 \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F9D1}\u{1F3FB}\u200D\u2764\uFE0F\u200D\u{1F48B}\u200D\u{1F9D1}\u{1F3FE}": "\u043F\u043E\u0446\u0435\u043B\u0443\u0439: \u0432\u0437\u0440\u043E\u0441\u043B\u044B\u0439 \u0432\u0437\u0440\u043E\u0441\u043B\u044B\u0439 \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F9D1}\u{1F3FB}\u200D\u2764\uFE0F\u200D\u{1F48B}\u200D\u{1F9D1}\u{1F3FF}": "\u043F\u043E\u0446\u0435\u043B\u0443\u0439: \u0432\u0437\u0440\u043E\u0441\u043B\u044B\u0439 \u0432\u0437\u0440\u043E\u0441\u043B\u044B\u0439 \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F9D1}\u{1F3FC}\u200D\u2764\uFE0F\u200D\u{1F48B}\u200D\u{1F9D1}\u{1F3FB}": "\u043F\u043E\u0446\u0435\u043B\u0443\u0439: \u0432\u0437\u0440\u043E\u0441\u043B\u044B\u0439 \u0432\u0437\u0440\u043E\u0441\u043B\u044B\u0439 \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u043E\u0447\u0435\u043D\u044C \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F9D1}\u{1F3FC}\u200D\u2764\uFE0F\u200D\u{1F48B}\u200D\u{1F9D1}\u{1F3FD}": "\u043F\u043E\u0446\u0435\u043B\u0443\u0439: \u0432\u0437\u0440\u043E\u0441\u043B\u044B\u0439 \u0432\u0437\u0440\u043E\u0441\u043B\u044B\u0439 \u0441\u0432\u0435\u0442\u043B\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438 \u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
