    "\u{1F469}\u{1F3FF}\u200D\u2764\uFE0F\u200D\u{1F469}\u{1F3FF}": "\u0432\u043B\u044E\u0431\u043B\u0435\u043D\u043D\u0430\u044F \u043F\u0430\u0440\u0430: \u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u043E\u0447\u0435\u043D\u044C \u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u043E\u043D \u043A\u043E\u0436\u0438",
    "\u{1F468}\u200D\u{1F469}\u200D\u{1F466}": "\u0441\u0435\u043C\u044C\u044F: \u043C\u0443\u0436\u0447\u0438\u043D\u0430 \u0436\u0435\u043D\u0449\u0438\u043D\u0430 \u043C\u0430\u043B\u044C\u0447\u0438\u043A",
